```mswea_bash_command
cat > /app/common.py <<'EOF'
import json,base64,re
from aiohttp import web
import db
class HTTPError(Exception):
 def __init__(self,status,message='error'): self.status=status; self.message=message
@web.middleware
async def error_middleware(request,handler):
 try: return await handler(request)
 except HTTPError as e: return web.json_response({'error':e.message},status=e.status)
 except web.HTTPException: raise
 except Exception as e: return web.json_response({'error':str(e)},status=500)
async def read_json(request):
 try: return await request.json()
 except: raise HTTPError(400,'invalid json')
def require_user(request):
 h=request.headers.get('Authorization','')
 if not h.startswith('Bearer '): raise HTTPError(401,'unauthorized')
 r=db.conn.execute('SELECT user_id FROM tokens WHERE token=?',(h[7:],)).fetchone()
 if not r: raise HTTPError(401,'unauthorized')
 return r['user_id']
def user_to_json(r):
 return {'id':r['id'],'username':r['username'],'display_name':r['display_name'],'timezone':r['timezone'] or 'UTC','avatar_url':r['avatar_url'] or '','status_text':r['status_text'] or '','status_emoji':r['status_emoji'] or ''}
def parse_limit(request):
 try: n=int(request.query.get('limit','50'))
 except: raise HTTPError(400,'invalid limit')
 if n<1 or n>200: raise HTTPError(400,'invalid limit')
 return n
def encode_cursor(n): return base64.urlsafe_b64encode(str(n).encode()).decode()
def decode_cursor(s):
 try: return int(base64.urlsafe_b64decode(s.encode()).decode())
 except: raise HTTPError(400,'invalid cursor')
def emit_event(channel_id,kind,data):
 r=db.conn.execute('SELECT last_event_id FROM channels WHERE id=?',(channel_id,)).fetchone()
 if not r: return 0
 eid=r['last_event_id']+1
 db.conn.execute('UPDATE channels SET last_event_id=? WHERE id=?',(eid,channel_id))
 db.conn.execute('INSERT INTO events(channel_id,event_id,kind,data,created_at) VALUES(?,?,?,?,?)',(channel_id,eid,kind,json.dumps(data),db.now_iso()))
 return eid
def broadcast_global(payload): return None
EOF
cat > /app/routes_auth.py <<'EOF'
import re,hashlib,secrets
from aiohttp import web
import db
from common import *
def pw(x): return hashlib.sha256(('huddle:'+x).encode()).hexdigest()
def setup(app):
 async def register(q):
  x=await read_json(q); u=x.get('username'); p=x.get('password')
  if not isinstance(u,str) or not re.fullmatch(r'[A-Za-z0-9_]{1,32}',u) or not isinstance(p,str) or len(p)<8: raise HTTPError(400,'invalid credentials')
  if db.conn.execute('SELECT 1 FROM users WHERE username=?',(u,)).fetchone(): raise HTTPError(409,'username exists')
  t=db.now_iso(); cur=db.conn.execute('INSERT INTO users(username,password_hash,display_name,created_at) VALUES(?,?,?,?)',(u,pw(p),x.get('display_name') or u,t))
  r=db.conn.execute('SELECT * FROM users WHERE id=?',(cur.lastrowid,)).fetchone(); tok=secrets.token_hex(24); db.conn.execute('INSERT INTO tokens VALUES(?,?,?)',(tok,r['id'],t))
  return web.json_response({'user':user_to_json(r),'token':tok},status=201)
 async def login(q):
  x=await read_json(q); r=db.conn.execute('SELECT * FROM users WHERE username=? AND password_hash=?',(x.get('username'),pw(x.get('password','')))).fetchone()
  if not r: raise HTTPError(401,'invalid credentials')
  tok=secrets.token_hex(24); db.conn.execute('INSERT INTO tokens VALUES(?,?,?)',(tok,r['id'],db.now_iso()))
  return web.json_response({'user':user_to_json(r),'token':tok})
 async def me(q):
  uid=require_user(q); return web.json_response({'user':user_to_json(db.conn.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone())})
 app.router.add_post('/api/auth/register',register); app.router.add_post('/api/auth/login',login); app.router.add_get('/api/auth/me',me)
EOF
cat > /app/server.py <<'EOF'
import argparse
from aiohttp import web
import db
from common import error_middleware
async def health(r): return web.json_response({'status':'ok','node_id':r.app['node_id']})
def main():
 p=argparse.ArgumentParser(); p.add_argument('--port',type=int); p.add_argument('--node-id',type=int); a=p.parse_args()
 db.init_db(); app=web.Application(middlewares=[error_middleware],client_max_size=20*1024*1024); app['node_id']=a.node_id
 async def root(r): return web.Response(text='<html><body><h1>Huddle</h1></body></html>',content_type='text/html')
 app.router.add_get('/',root); app.router.add_get('/api/health',health)
 import routes_auth; routes_auth.setup(app)
 web.run_app(app,host='0.0.0.0',port=a.port)
if __name__=='__main__': main()
EOF
bash /spec/tools/restart.sh && bash /spec/base/checks/check_base.sh && bash /spec/a/checks/check_a_1.sh
```

