  const form = document.querySelector('[data-testid="auth-form"]');
  const error = form && form.querySelector('.error');
  const api = async (url, opts={}) => {
    opts.headers = Object.assign({'Content-Type':'application/json'}, opts.headers||{});
    if (token) opts.headers.Authorization = 'Bearer '+token;
    const r = await fetch(url, opts);
    const d = await r.json().catch(()=>({}));
    if (!r.ok) throw new Error(d.error || 'Request failed');
    return d;
  };
  if (token && modal) modal.hidden = true;
  const toggle = document.querySelector('[data-testid="auth-toggle"]');
  if (toggle) toggle.onclick = () => {
    const signup = form.dataset.mode !== 'signup'; form.dataset.mode = signup ? 'signup' : 'login';
    form.querySelector('.auth-title').textContent = signup ? 'Sign up for Huddle' : 'Log in to Huddle';
    form.querySelector('[data-testid="auth-submit"]').textContent = signup ? 'Sign up' : 'Log in';
    toggle.textContent = signup ? 'Already have an account? Log in' : 'Need an account? Sign up';
    form.querySelector('.signup-only').hidden = !signup;
  };
  if (form) form.onsubmit = async e => {
