        username:fd.get('username'), password:fd.get('password'), ...(signup ? {display_name:fd.get('display_name')} : {})
      })});
      localStorage.setItem('huddle.token', d.token); location.reload();
    } catch (x) { error.textContent = x.message; }
  };
  const logout = document.querySelector('[data-testid="logout-btn"]');
  if (logout) logout.onclick = () => { localStorage.removeItem('huddle.token'); location.reload(); };
})();
