  $(T('logout-btn')).onclick=()=>{localStorage.removeItem('huddle.token');location.reload()};
  const wf=$(T('workspace-create-form'));if(wf)wf.onsubmit=async e=>{e.preventDefault();const f=new FormData(wf);try{const d=await api('/api/workspaces',{method:'POST',body:{slug:f.get('slug'),name:f.get('name')}});workspace={workspace:d.workspace,channels:[d.general_channel]};$(T('empty-state-create-workspace')).hidden=true;$('.ws-name').textContent=d.workspace.name;const cl=$(T('channel-list'));cl.innerHTML='';cl.appendChild(entry(d.general_channel));select(d.general_channel)}catch(x){let a=wf.querySelector('[role="alert"]')||document.createElement('div');a.setAttribute('role','alert');a.textContent=x.message;wf.appendChild(a)}};
  const cm=$('#create-channel-modal'), nf=$(T('new-channel-btn')), cf=$(T('create-channel-form'));
  if(nf)nf.onclick=()=>{cm.hidden=false};$(T('create-channel-cancel')).onclick=()=>cm.hidden=true;
  if(cf)cf.onsubmit=async e=>{e.preventDefault();const f=new FormData(cf),a=cf.querySelector('[role="alert"]')||document.createElement('div');a.setAttribute('role','alert');try{const d=await api('/api/workspaces/'+workspace.workspace.slug+'/channels',{method:'POST',body:{name:f.get('name'),is_private:f.get('is_private')==='on'}});a.textContent='';channels.push(d.channel);$(T('channel-list')).appendChild(entry(d.channel));cm.hidden=true;select(d.channel)}catch(x){a.textContent=x.message;cf.appendChild(a)}};
  load();
})();
